import { useState } from "react";
import { priceData } from "./priceData";
import styles from "./PriceComponent.module.css";

function PriceComponent() {
  // По умолчанию открываем кровлю, так как она у нас базовая по макету
  const [activeTab, setActiveTab] = useState("кровля");

  // Автоматически получаем список категорий из ключей priceData
  const categories = Object.keys(priceData);

  return (
    <section className={styles.priceSection}>
      {/* Шапка блока с линиями по бокам, в стиле вашей галереи */}
      <div className={styles.headerRow}>
        <span className={`${styles.line} ${styles.lineLeft}`} />
        <span className={styles.title}>ПРАЙС-ЛИСТ</span>
        <span className={`${styles.line} ${styles.lineRight}`} />
      </div>

      {/* Горизонтальное меню табов */}
      <div className={styles.tabsMenu}>
        {categories.map((cat) => (
          <button
            key={cat}
            className={`${styles.tabButton} ${activeTab === cat ? styles.activeTab : ""}`}
            onClick={() => setActiveTab(cat)}
          >
            {cat.toUpperCase()}
          </button>
        ))}
      </div>

      {/* Временный текстовый маркер для проверки кликов */}
      <div style={{ color: "#fff", marginTop: "20px", textTransform: "uppercase", textAlign: "center" }}>
        Активный раздел: {activeTab}
      </div>
    </section>
  );
}

export default PriceComponent;
